CREATE TABLE "c_Author" ("id" BIGINT NOT NULL, "a_Author_display_name" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Comment" ("id" BIGINT NOT NULL, "a_Comment_body" TEXT NOT NULL, "r_PostComments_source_id" BIGINT, "r_PostComments_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_PostComments_source_dtype" IS NULL OR "r_PostComments_source_dtype" IN ('Post','SponsoredPost')), CHECK ((TRUE) OR "r_PostComments_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_PostComments_source_id" IS NOT NULL));
CREATE TABLE "c_Post" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Post_title" TEXT, "a_Post_body" TEXT, "a_SponsoredPost_campaign_code" TEXT, "r_AuthorPosts_source_id" BIGINT, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Post','SponsoredPost')), CHECK ((dtype IN ('Post','SponsoredPost')) OR "a_Post_title" IS NULL), CHECK (NOT (dtype IN ('Post','SponsoredPost')) OR "a_Post_title" IS NOT NULL), CHECK ((dtype IN ('Post','SponsoredPost')) OR "a_Post_body" IS NULL), CHECK (NOT (dtype IN ('Post','SponsoredPost')) OR "a_Post_body" IS NOT NULL), CHECK ((dtype IN ('SponsoredPost')) OR "a_SponsoredPost_campaign_code" IS NULL), CHECK (NOT (dtype IN ('SponsoredPost')) OR "a_SponsoredPost_campaign_code" IS NOT NULL), CHECK ((dtype IN ('Post','SponsoredPost')) OR "r_AuthorPosts_source_id" IS NULL), CHECK (NOT (dtype IN ('Post','SponsoredPost')) OR "r_AuthorPosts_source_id" IS NOT NULL));
CREATE TABLE "c_Tag" ("id" BIGINT NOT NULL, "a_Tag_label" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "l_PostTags" ("r_PostTags_source_id" BIGINT NOT NULL, "r_PostTags_source_dtype" TEXT NOT NULL, "r_PostTags_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_PostTags_source_id", "r_PostTags_target_id"), CHECK ("r_PostTags_source_dtype" IS NULL OR "r_PostTags_source_dtype" IN ('Post','SponsoredPost')));
